package com.jenkinskg.pings
import android.app.*;import android.os.*;import android.content.*;import android.net.*;import android.widget.*;import java.net.*;import java.util.concurrent.*
data class Dev(val ip:String,val host:String,val up:Boolean,val ms:Long,val type:String)
class MainActivity:Activity(){lateinit var subnet:EditText;lateinit var list:ListView;lateinit var counts:TextView;var devs=listOf<Dev>();var before=listOf<Dev>();val pool=Executors.newFixedThreadPool(32)
override fun onCreate(b:Bundle?){super.onCreate(b);val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};subnet=EditText(this).apply{setText("192.168.1.0/24")};val row=LinearLayout(this);fun button(t:String,f:()->Unit)=Button(this).apply{text=t;setOnClickListener{f()}};row.addView(button("Current Subnet"){subnet.setText(currentSubnet())});row.addView(button("Scan"){scan()});row.addView(button("Set Before"){before=devs});row.addView(button("Compare"){show(true)});counts=TextView(this);list=ListView(this);root.addView(subnet);root.addView(row);root.addView(counts);root.addView(list,LinearLayout.LayoutParams(-1,0,1f));setContentView(root)}
fun currentSubnet():String{val cm=getSystemService(CONNECTIVITY_SERVICE) as ConnectivityManager;for(n in cm.allNetworks){val lp=cm.getLinkProperties(n)?:continue;for(a in lp.linkAddresses)if(a.address is Inet4Address&&!a.address.isLoopbackAddress){val p=a.prefixLength;val x=a.address.address.map{it.toInt()and 255};val v=(x[0] shl 24)or(x[1] shl 16)or(x[2] shl 8)or x[3];val mask=-1 shl(32-p);val q=v and mask;return ((q ushr 24)and255).toString()+"."+((q ushr16)and255)+"."+((q ushr8)and255)+"."+(q and255)+"/"+p}};return "192.168.1.0/24"}
fun scan(){val z=subnet.text.toString().split("/");if(z.size!=2)return;val p=z[1].toIntOrNull()?:return;if(p<16||p>30)return;val a=InetAddress.getByName(z[0]).address.map{it.toInt()and255};val base=((a[0].toLong()shl24)or(a[1].toLong()shl16)or(a[2].toLong()shl8)or a[3].toLong()) and (0xffffffffL shl(32-p));val max=minOf((1L shl(32-p))-2,4094);val out=java.util.Collections.synchronizedList(mutableListOf<Dev>());counts.text="Scanning...";Thread{val fs=(1..max).map{i->pool.submit{val v=base+i;val ip=((v shr24)and255).toString()+"."+((v shr16)and255)+"."+((v shr8)and255)+"."+(v and255);val t=System.currentTimeMillis();val up=try{InetAddress.getByName(ip).isReachable(700)}catch(e:Exception){false};val h=if(up)try{InetAddress.getByName(ip).canonicalHostName}catch(e:Exception){""}else"";val type=if(h.contains("aruba",true)||h.contains("cisco",true)||h.startsWith("ap",true))"Access Point" else if(h.contains("pc",true)||h.contains("desktop",true)||h.contains("laptop",true))"PC / Desktop" else "Unknown";out.add(Dev(ip,h,up,if(up)System.currentTimeMillis()-t else -1,type))}};fs.forEach{it.get()};devs=out.toList();runOnUiThread{show(false)}}.start()}
fun show(c:Boolean){val old=before.associateBy{it.ip};val lines=devs.filter{it.up}.map{d->d.ip+"  "+d.host+"  "+d.type+"  "+d.ms+"ms"+if(c&&!old.containsKey(d.ip))" NEW" else""}.toMutableList();if(c)lines.addAll(before.filter{it.up&&!devs.any{n->n.ip==it.ip&&n.up}}.map{it.ip+" "+it.host+" MISSING"});list.adapter=ArrayAdapter(this,android.R.layout.simple_list_item_1,lines);counts.text="Pingable "+devs.count{it.up}+" | AP "+devs.count{it.up&&it.type=="Access Point"}+" | Unknown "+devs.count{it.up&&it.type=="Unknown"}+" | No Ping "+devs.count{!it.up}}
}